  group('Capture goldens (§7)', () {
    // The store only matters on Save; goldens never save, but the Review
    // sheet requires the full service bundle, so point it at one temp dir.
    late Directory store;
    setUp(() => store = Directory.systemTemp.createTempSync('gold-attach'));
    tearDown(() => store.deleteSync(recursive: true));

    CaptureServices cap(List<String> lines) => CaptureServices(
      intake: _GoldIntake(),
      extractor: _GoldExtractor(lines),
      store: AttachmentStore(store),
    );

    const highConf = [
      'GREENGROCER MARKET',
      '123 MAIN ST',
      '2026-10-28',
      'BANANAS 2.19',
      'TOTAL 12.34',
    ];
    const lowConf = [
      'CORNER STORE',
      '03/04/2026',
      'SUBTOTAL 8.00',
      'AMOUNT 9.50',
    ];

    for (final brightness in Brightness.values) {
      final mode = modeName(brightness);

      testWidgets('ledger with secondary capture FAB — $mode', (tester) async {
        usePhoneViewport(tester);
        final db = AppDatabase.inMemory();
        final repo = LedgerRepository(db);
        try {
          await repo.ensureDefaults();
          await pumpFullApp(tester, brightness, repo, capture: cap(highConf));
          await expectLater(
            find.byType(LocalBudgetApp),
            matchesGoldenFile('goldens/ledger_with_capture_fab_$mode.png'),
          );
        } finally {
          await db.close();
        }
      });

      testWidgets('source sheet — $mode', (tester) async {
        usePhoneViewport(tester);
        final db = AppDatabase.inMemory();
        final repo = LedgerRepository(db);
        try {
          await repo.ensureDefaults();
          await pumpFullApp(tester, brightness, repo, capture: cap(highConf));
          await tester.tap(find.byKey(const ValueKey('receipt-add-document')));
          await tester.pumpAndSettle();
          await expectLater(
            find.byType(BottomSheet),
            matchesGoldenFile('goldens/capture_source_sheet_$mode.png'),
          );
        } finally {
          await db.close();
        }
      });

      Future<void> reviewGolden(
        WidgetTester tester,
        List<String> lines,
        String name,
      ) async {
        usePhoneViewport(tester);
        final db = AppDatabase.inMemory();
        final repo = LedgerRepository(db);
        try {
          await repo.ensureDefaults();
          await pumpFullApp(tester, brightness, repo, capture: cap(lines));
          await tester.tap(find.byKey(const ValueKey('receipt-add-document')));
          await tester.pumpAndSettle();
          await tester.tap(find.byKey(const Key('capture-camera')));
          await tester.pumpAndSettle();
          await expectLater(
            find.byType(BottomSheet),
            matchesGoldenFile(
              'goldens/$name'
              '_$mode.png',
            ),
          );
        } finally {
          await db.close();
        }
      }

      testWidgets('review populated — $mode', (tester) async {
        await reviewGolden(tester, highConf, 'review_populated');
      });

      testWidgets('review low confidence — $mode', (tester) async {
        await reviewGolden(tester, lowConf, 'review_low_confidence');
      });
    }
  });

  // E2 §7 / issue #30: one article page stands in for the Help reading
  // surface; it is reached by real navigation so the back affordance is
  // part of the shot.
  group('Help golden', () {
    for (final brightness in Brightness.values) {
      final mode = modeName(brightness);
      testWidgets('article page — $mode', (tester) async {
        usePhoneViewport(tester);
