  // E3 issue #39: the budgets sheet in its three money states plus the
  // goal detail. All seeded data carries fixed dates so the shots are
  // pixel-stable between golden regenerations; only the sheet's own month
  // header follows the calendar, exactly like the ledger goldens above.
  group('Budgets & goals goldens (E3)', () {
    for (final brightness in Brightness.values) {
      final mode = modeName(brightness);

      testWidgets('budgets empty — $mode', (tester) async {
        usePhoneViewport(tester);
        final db = AppDatabase.inMemory();
        final repo = LedgerRepository(db);
        try {
          await repo.ensureDefaults();
          await pumpFullApp(tester, brightness, repo);
          // The 2026-11-05 IA pass moved the sheet behind Manage: the
          // Expenses stat now switches the home panel in place.
          await tester.tap(find.byKey(const Key('manage-open')));
          await tester.pumpAndSettle();
          await tester.tap(find.text('Budgets & bills'));
          await tester.pumpAndSettle();
          await expectLater(
            find.byType(BottomSheet),
            matchesGoldenFile('goldens/budgets_empty_$mode.png'),
          );
        } finally {
          await db.close();
        }
      });

      testWidgets('budgets rows with rollover and overspend — $mode', (
        tester,
      ) async {
        usePhoneViewport(tester);
        final db = AppDatabase.inMemory();
        final repo = LedgerRepository(db);
        try {
          await repo.ensureDefaults();
          final now = DateTime.now();
          final ym = yearMonthOf(DateTime(now.year, now.month, 15));
          final prev = DateTime(now.year, now.month - 1, 15);
          final prevYm = yearMonthOf(prev);
          final acc = await repo.defaultAccount();
          final food = await repo.addCategory('Food');
          final rent = await repo.addCategory('Rent');
          await repo.setBudgetRollover(true);
          // Last month: $10 of a $30 Food budget → +$20 rolls forward.
          await repo.setBudget(
            categoryId: food,
            yearMonth: prevYm,
            limitMinor: 30000,
            currencyCode: 'USD',
          );
          await repo.addTransaction(
            accountId: acc.id,
            date: prev,
            amount: usd(10000),
            source: TransactionSource.manual,
            categoryId: food,
          );
          // This month: Food carries into $220 with $50 spent; Rent is
          // overspent ($7 of $5) and carries its hole as progress bar.
          await repo.setBudget(
            categoryId: food,
            yearMonth: ym,
            limitMinor: 20000,
            currencyCode: 'USD',
          );
          await repo.addTransaction(
            accountId: acc.id,
            date: DateTime(now.year, now.month, 1),
            amount: usd(5000),
            source: TransactionSource.manual,
            categoryId: food,
          );
          await repo.setBudget(
            categoryId: rent,
            yearMonth: ym,
            limitMinor: 500,
            currencyCode: 'USD',
          );
          await repo.addTransaction(
            accountId: acc.id,
            date: DateTime(now.year, now.month, 1),
            amount: usd(700),
            source: TransactionSource.manual,
            categoryId: rent,
          );
          await pumpFullApp(tester, brightness, repo);
          await tester.tap(find.byKey(const Key('manage-open')));
          await tester.pumpAndSettle();
          await tester.tap(find.text('Budgets & bills'));
          await tester.pumpAndSettle();
          await expectLater(
            find.byType(BottomSheet),
            matchesGoldenFile('goldens/budgets_rows_$mode.png'),
          );
        } finally {
          await db.close();
        }
      });

      testWidgets('bills list — $mode', (tester) async {
        usePhoneViewport(tester);
        final db = AppDatabase.inMemory();
        final repo = LedgerRepository(db);
        try {
          await repo.ensureDefaults();
          // One overdue bill (red, leads the list) and two far-future
          // ones; the dates are fixed points, never offsets from today.
          await repo.addRule(
            name: 'Electric',
            amountMinor: 8450,
            currencyCode: 'USD',
            frequency: 'monthly',
            dayOfMonth: 5,
            start: DateTime(2026, 1, 5),
            nextDue: DateTime(2026, 10, 5),
          );
          await repo.addRule(
            name: 'Streaming',
            amountMinor: 1599,
            currencyCode: 'USD',
            frequency: 'monthly',
            dayOfMonth: 1,
            start: DateTime(2025, 3, 1),
            nextDue: DateTime(2027, 3, 1),
          );
          await repo.addRule(
            name: 'Internet',
            amountMinor: 5900,
            currencyCode: 'USD',
            frequency: 'monthly',
            dayOfMonth: 30,
            start: DateTime(2025, 6, 30),
            nextDue: DateTime(2027, 6, 30),
          );
          await pumpFullApp(tester, brightness, repo);
          await tester.tap(find.byKey(const Key('manage-open')));
          await tester.pumpAndSettle();
          await tester.tap(find.text('Budgets & bills'));
          await tester.pumpAndSettle();
          // Scoped: the home bar behind the barrier also says 'Bills'.
          await tester.tap(
            find.descendant(
              of: find.byType(BottomSheet),
              matching: find.text('Bills'),
            ),
          );
          await tester.pumpAndSettle();
          await expectLater(
            find.byType(BottomSheet),
            matchesGoldenFile('goldens/bills_list_$mode.png'),
          );
        } finally {
          await db.close();
        }
      });

      testWidgets('goal detail — $mode', (tester) async {
        usePhoneViewport(tester);
        final db = AppDatabase.inMemory();
        final repo = LedgerRepository(db);
        try {
          await repo.ensureDefaults();
          final acc = await repo.defaultAccount();
          final goalId = await repo.addGoal(
            name: 'Emergency fund',
            currencyCode: 'USD',
            targetMinor: 500000,
          );
          await repo.addGoalTransfer(
            accountId: acc.id,
            goalId: goalId,
            date: DateTime(2026, 10, 2),
            amount: usd(150000),
          );
          await repo.addGoalTransfer(
            accountId: acc.id,
            goalId: goalId,
            date: DateTime(2026, 10, 20),
            amount: usd(50000),
          );
          await repo.addGoalTransfer(
            accountId: acc.id,
            goalId: goalId,
            date: DateTime(2026, 10, 28),
            amount: usd(20000),
            isIncome: true,
          );
          final goal = (await repo.goals()).single;
          await tester.pumpWidget(
            goldHost(
              brightness: brightness,
              child: Builder(
                builder: (context) => TextButton(
                  onPressed: () => showGoalDetail(
                    context,
                    repository: repo,
                    line: GoalLine(
                      goal: goal,
