              ),
            ),
          );
          await tester.tap(find.text('open'));
          await tester.pumpAndSettle();
          await expectLater(
            find.byType(BottomSheet),
            matchesGoldenFile('goldens/goal_detail_$mode.png'),
          );
        } finally {
          await db.close();
