  // E4 issue #5: the three Reports segments. Data sits on fixed calendar
  // dates inside the previous or early current months, so every figure is
  // stable between regenerations; the Month shot reads the PREVIOUS month
  // deliberately — a finished month has no pace figure, so no KPI depends
  // on how far into the month "today" happens to be.
  group('Reports goldens (E4)', () {
    for (final brightness in Brightness.values) {
      final mode = modeName(brightness);

      Future<void> openReports(WidgetTester tester) async {
        await tester.tap(find.byKey(Key('reports-open')));
        await tester.pumpAndSettle();
      }

      testWidgets('month — $mode', (tester) async {
        usePhoneViewport(tester);
        final db = AppDatabase.inMemory();
        final repo = LedgerRepository(db);
        try {
          await repo.ensureDefaults();
          final now = DateTime.now();
          final m = DateTime(now.year, now.month - 1);
          final acc = await repo.defaultAccount();
          final food = await repo.addCategory('Food');
          final rent = await repo.addCategory('Rent');
          final transport = await repo.addCategory('Transport');
          await repo.addTransaction(
            accountId: acc.id,
            date: DateTime(m.year, m.month, 3),
            amount: usd(120000),
            source: TransactionSource.manual,
            categoryId: rent,
          );
          await repo.addTransaction(
            accountId: acc.id,
            date: DateTime(m.year, m.month, 9),
            amount: usd(4250),
            source: TransactionSource.manual,
            categoryId: food,
            merchant: 'Green Grocer',
          );
          await repo.addTransaction(
            accountId: acc.id,
            date: DateTime(m.year, m.month, 12),
            amount: usd(1825),
            source: TransactionSource.manual,
            categoryId: food,
            merchant: 'Corner Cafe',
          );
          await repo.addTransaction(
            accountId: acc.id,
            date: DateTime(m.year, m.month, 20),
            amount: usd(1240),
            source: TransactionSource.manual,
            categoryId: transport,
            merchant: 'Metro Card',
          );
          await pumpFullApp(tester, brightness, repo);
          await openReports(tester);
          // A finished month: deterministic KPIs, honest denominators.
          await tester.tap(find.byKey(Key('month-prev')));
          await tester.pumpAndSettle();
          await expectLater(
            find.byType(ReportsScreen),
            matchesGoldenFile('goldens/reports_month_$mode.png'),
          );
        } finally {
          await db.close();
        }
      });

      testWidgets('year — $mode', (tester) async {
        usePhoneViewport(tester);
        final db = AppDatabase.inMemory();
        final repo = LedgerRepository(db);
        try {
          await repo.ensureDefaults();
          final now = DateTime.now();
          final y = now.year;
          final acc = await repo.defaultAccount();
          final food = await repo.addCategory('Food');
          final rent = await repo.addCategory('Rent');
          // Four settled months of the current year — the bar chart is
          // twelve slots regardless, empty months render as zeros.
          for (final (month, minor, cat) in [
            (1, 98050, rent),
            (3, 25000, food),
            (5, 48125, food),
            (7, 32480, food),
          ]) {
            await repo.addTransaction(
              accountId: acc.id,
              date: DateTime(y, month, 10),
              amount: usd(minor),
              source: TransactionSource.manual,
              categoryId: cat,
            );
          }
          await pumpFullApp(tester, brightness, repo);
          await openReports(tester);
          await tester.tap(find.text('Year'));
          await tester.pumpAndSettle();
          await expectLater(
            find.byType(ReportsScreen),
            matchesGoldenFile('goldens/reports_year_$mode.png'),
          );
        } finally {
          await db.close();
        }
      });

      testWidgets('actual — $mode', (tester) async {
        usePhoneViewport(tester);
        final db = AppDatabase.inMemory();
        final repo = LedgerRepository(db);
        try {
          await repo.ensureDefaults();
          final now = DateTime.now();
          final ym = yearMonthOf(DateTime(now.year, now.month, 15));
          final prevYm = yearMonthOf(DateTime(now.year, now.month - 1, 15));
          final acc = await repo.defaultAccount();
          final food = await repo.addCategory('Food');
          final rent = await repo.addCategory('Rent');
          await repo.setBudgetRollover(true);
          // Food carries +$20 forward into a $200 limit; Rent runs over
          // its tiny limit; the overall target frames the whole month.
          await repo.setBudget(
            categoryId: food,
            yearMonth: prevYm,
            limitMinor: 30000,
            currencyCode: 'USD',
          );
          await repo.addTransaction(
            accountId: acc.id,
            date: DateTime(now.year, now.month - 1, 15),
            amount: usd(10000),
            source: TransactionSource.manual,
            categoryId: food,
          );
          await repo.setBudget(
            categoryId: food,
            yearMonth: ym,
            limitMinor: 20000,
            currencyCode: 'USD',
          );
          await repo.addTransaction(
            accountId: acc.id,
            date: DateTime(now.year, now.month, 1),
            amount: usd(5000),
            source: TransactionSource.manual,
            categoryId: food,
          );
          await repo.setBudget(
            categoryId: rent,
            yearMonth: ym,
            limitMinor: 500,
            currencyCode: 'USD',
          );
          await repo.addTransaction(
            accountId: acc.id,
            date: DateTime(now.year, now.month, 1),
            amount: usd(700),
            source: TransactionSource.manual,
            categoryId: rent,
          );
          await repo.setBudget(
            yearMonth: ym,
            limitMinor: 40000,
            currencyCode: 'USD',
          );
          await pumpFullApp(tester, brightness, repo);
          await openReports(tester);
          await tester.tap(find.text('Actual'));
          await tester.pumpAndSettle();
          await expectLater(
            find.byType(ReportsScreen),
            matchesGoldenFile('goldens/reports_actual_$mode.png'),
          );
        } finally {
          await db.close();
        }
      });
    }
  });
  // E6 §8: the support surface. Rendered standalone — these flows hang off
  // ManageScreen/GetProPage, not the full app, and the billing side is the
  // §4 fake gateway, so every pixel (catalog, prices, receipt) is pinned.
  group('E6 support goldens', () {
    // dispose() cancels a stream subscription; awaiting that inside a
    // testWidgets body deadlocks the fake-async zone (the cancel microtask
    // can never run while the body is blocked). coffee_test's proven
    // pattern: hold the service and dispose it in tearDown.
    TipService? held;
    tearDown(() async {
      await held?.dispose();
      held = null;
    });

    for (final brightness in Brightness.values) {
      final mode = modeName(brightness);

      Future<void> pumpManage(
        WidgetTester tester,
        LedgerRepository repo, {
        TipService? tips,
      }) async {
        await tester.pumpWidget(
          MaterialApp(
            theme: goldTheme(Brightness.light),
            darkTheme: goldTheme(Brightness.dark),
            themeMode: brightness == Brightness.light
                ? ThemeMode.light
                : ThemeMode.dark,
            home: ManageScreen(repository: repo, tips: tips),
          ),
        );
        await tester.pumpAndSettle();
        await tester.dragUntilVisible(
          find.byKey(const Key('coffee')),
          find.byType(ListView),
          const Offset(0, -240),
        );
        await tester.pumpAndSettle();
      }

      testWidgets('support rows — $mode', (tester) async {
        usePhoneViewport(tester);
        final db = AppDatabase.inMemory();
        final repo = LedgerRepository(db);
        final tips = held = TipService(
          gateway: FakeBillingGateway(),
          kv: _GoldKv(),
        );
        try {
          await repo.ensureDefaults();
          await pumpManage(tester, repo, tips: tips);
          // Support section sits just above About & help; keep scrolling so
          // both headers are in frame — this is the discovery shot.
          await tester.dragUntilVisible(
            find.text('About & help'),
            find.byType(ListView),
            const Offset(0, -240),
          );
          await tester.pumpAndSettle();
          await expectLater(
            find.byType(ManageScreen),
            matchesGoldenFile('goldens/manage_support_rows_$mode.png'),
          );
        } finally {
          await db.close();
        }
      });

      testWidgets('coffee sheet — $mode', (tester) async {
        usePhoneViewport(tester);
        final db = AppDatabase.inMemory();
        final repo = LedgerRepository(db);
        final tips = held = TipService(
          gateway: FakeBillingGateway(),
          kv: _GoldKv(),
        );
        try {
          await repo.ensureDefaults();
          await pumpManage(tester, repo, tips: tips);
          await tester.tap(find.byKey(const Key('coffee')));
          await tester.pumpAndSettle();
          await expectLater(
            find.byType(BottomSheet),
            matchesGoldenFile('goldens/coffee_sheet_$mode.png'),
          );
        } finally {
          await db.close();
        }
      });

      testWidgets('get pro page — $mode', (tester) async {
        usePhoneViewport(tester);
        await tester.pumpWidget(
          MaterialApp(
            theme: goldTheme(Brightness.light),
            darkTheme: goldTheme(Brightness.dark),
            themeMode: brightness == Brightness.light
                ? ThemeMode.light
                : ThemeMode.dark,
            home: GetProPage(
              transfer: FakeFreeTransfer(),
              onCopyData: () async {},
            ),
          ),
        );
        await tester.pumpAndSettle();
        await expectLater(
          find.byType(GetProPage),
          matchesGoldenFile('goldens/getpro_page_$mode.png'),
        );
      });
    }

    // The thanks state is a one-shot celebration; one light render is the
    // pin (§8 keeps the ref count honest — five states, seven refs).
    testWidgets('coffee thanks — light', (tester) async {
      usePhoneViewport(tester);
      final db = AppDatabase.inMemory();
      final repo = LedgerRepository(db);
      final tips = held = TipService(
        gateway: FakeBillingGateway(),
        kv: _GoldKv(),
      );
      try {
        await repo.ensureDefaults();
        await tester.pumpWidget(
          MaterialApp(
            theme: goldTheme(Brightness.light),
            darkTheme: goldTheme(Brightness.dark),
            themeMode: ThemeMode.light,
            home: ManageScreen(repository: repo, tips: tips),
          ),
        );
        await tester.pumpAndSettle();
        await tester.dragUntilVisible(
          find.byKey(const Key('coffee')),
          find.byType(ListView),
          const Offset(0, -240),
        );
        await tester.pumpAndSettle();
        await tester.tap(find.byKey(const Key('coffee')));
        await tester.pumpAndSettle();
        await tester.tap(find.byKey(const Key('coffee-buy')));
        await tester.pumpAndSettle();
        await expectLater(
          find.byType(BottomSheet),
          matchesGoldenFile('goldens/coffee_thanks_light.png'),
        );
      } finally {
        await db.close();
      }
    });
  });

  // E11 M4 — the document route's three shipped surfaces. Fixed 2026-12
  // fixture dates: past the parser windows (~Q1 2027) the pixels move
  // honestly with the calendar — play goldens:generate again, same deal
  // as the calendar-following sheets above.
  group('Document import goldens (E11)', () {
    // Dot-decimal with a running-balance column — the shape the §6 corpus
    // renders and the one the maskDates fix (6449fa4) protects.
    const statement = [
      'NORTHFIELD CREDIT UNION',
      'ACCOUNT 4471 0296',
      'DATE DESCRIPTION AMOUNT BALANCE',
      '12/01/2026 CORNER FOOD MART 24.60 1,780.00',
      '12/03/2026 PAYROLL DEPOSIT +2,400.00 4,180.00',
      '12/05/2026 CITY TRANSIT CARD 38.00 4,142.00',
    ];
    // Utility-shaped bill (E2 signatures) with a day-past-12 due date —
    // the same unambiguous-date convention the corpora use.
    const bill = [
      'ACME ELECTRIC COMPANY',
      'ACCOUNT NUMBER 4471 2208',
      'SERVICE PERIOD OCT 01 - OCT 31',
      'NEW CHARGES 96.40',
      'AMOUNT DUE 84.00',
      'DUE DATE 12/16/2026',
      'PAY BY MAIL OR ONLINE',
    ];

    CaptureServices cap(List<String> lines) => CaptureServices(
      intake: _GoldIntake(),
      extractor: _GoldExtractor(lines),
    );

    Future<void> pumpApp(
      WidgetTester tester,
      Brightness b,
      LedgerRepository repo,
      AppDatabase db,
      List<String> lines,
    ) async {
      await tester.pumpWidget(
        LocalBudgetApp(
          repository: repo,
          db: db,
          capture: cap(lines),
          theme: goldTheme(Brightness.light),
          darkTheme: goldTheme(Brightness.dark),
          themeMode: b == Brightness.light
              ? ThemeMode.light
              : ThemeMode.dark,
        ),
      );
      await tester.pumpAndSettle();
    }

    Future<void> openWizard(WidgetTester tester) async {
      await tester.tap(find.byKey(const Key('manage-open')));
      await tester.pumpAndSettle();
      final importRow = find.byKey(const Key('import-statement'));
      await tester.scrollUntilVisible(
        importRow,
        300,
        scrollable: find.byType(Scrollable).first,
      );
      await tester.tap(importRow);
      await tester.pumpAndSettle();
    }

    Future<void> pickPhoto(WidgetTester tester) async {
      await tester.tap(find.byKey(const Key('import-pick-document')));
      await tester.pumpAndSettle();
      await tester.tap(find.text('Photos'));
      await tester.pumpAndSettle();
    }

    for (final mode in ['light', 'dark']) {
      final brightness = mode == 'light' ? Brightness.light : Brightness.dark;

      testWidgets('source panel with the document row — $mode', (
        tester,
      ) async {
        usePhoneViewport(tester);
        final db = AppDatabase.inMemory();
        final repo = LedgerRepository(db);
        await repo.ensureDefaults();
        try {
          await pumpApp(tester, brightness, repo, db, statement);
          await openWizard(tester);
          await expectLater(
            find.byType(ImportWizardScreen),
            matchesGoldenFile('goldens/import_source_$mode.png'),
          );
        } finally {
          await db.close();
        }
      });

      testWidgets('scanned statement preview, duplicate caught — $mode', (
        tester,
      ) async {
        usePhoneViewport(tester);
        final db = AppDatabase.inMemory();
        final repo = LedgerRepository(db);
        await repo.ensureDefaults();
        try {
          // The first scanned row is already in the account.
          final account = await repo.defaultAccount();
          await repo.addTransaction(
            accountId: account.id,
            date: DateTime(2026, 12, 1),
            amount: usd(2460),
            source: TransactionSource.manual,
            merchant: 'Corner Food Mart',
          );
          await pumpApp(tester, brightness, repo, db, statement);
          await openWizard(tester);
          await pickPhoto(tester);
          await expectLater(
            find.byType(ImportWizardScreen),
            matchesGoldenFile('goldens/import_preview_document_$mode.png'),
          );
        } finally {
          await db.close();
        }
      });

      testWidgets('photographed bill prefills the editor — $mode', (
        tester,
      ) async {
        usePhoneViewport(tester);
        final db = AppDatabase.inMemory();
        final repo = LedgerRepository(db);
        await repo.ensureDefaults();
        try {
          await pumpApp(tester, brightness, repo, db, bill);
          await openWizard(tester);
          await pickPhoto(tester);
          await expectLater(
            find.byType(BottomSheet),
            matchesGoldenFile('goldens/bill_prefill_document_$mode.png'),
          );
        } finally {
          await db.close();
        }
      });
    }
  });
}

/// E6 §4: throwaway kv for golden runs — receipts never pre-seed.
class _GoldKv implements SettingsKv {
  final _map = <String, String>{};
  @override
  Future<String?> get(String key) async => _map[key];
  @override
  Future<void> set(String key, String value) async => _map[key] = value;
}
